def check_polynomial(P, n, K):
    """Checks if P(k) is a multiple of n for k in K."""
    for k in K:
        value = 0
        # P is represented as a dictionary {degree: coefficient}
        for degree, coeff in P.items():
            value += coeff * (k ** degree)
        if value % n != 0:
            return False
    return True

def search_c2(n, K):
    """Searches for polynomials with 2 non-zero coefficients."""
    found_candidates = []

    # Possible degrees: 0, 1, 2, 3, 4
    degrees = [0, 1, 2, 3, 4]

    # Iterate over pairs of distinct degrees (i, j)
    for i in degrees:
        for j in degrees:
            if i == j:
                continue

            # We normalize by ensuring i > j to avoid redundant checks (P(x) vs P(x) reversed)
            if i < j:
                continue

            # The degree of the polynomial is i. We require i > 1.
            if i <= 1:
                continue

            # Iterate over signs
            for sign_i in [1, -1]:
                for sign_j in [1, -1]:
                    P = {i: sign_i, j: sign_j}

                    if check_polynomial(P, n, K):
                        # Store the polynomial definition (for identification)
                        found_candidates.append({
                            'coefficients': 2,
                            'P': P,
                            'description': f"P(x) = {sign_i}x^{i} + {sign_j}x^{j}"
                        })
    return found_candidates

