def search_c3(n, K):
    """Searches for polynomials with 3 non-zero coefficients."""
    found_candidates = []

    degrees = [0, 1, 2, 3, 4]

    # Iterate over triples of distinct degrees (i, j, k)
    for i in degrees:
        for j in degrees:
            for k in degrees:
                if i == j or i == k or j == k:
                    continue

                # Sort degrees to handle permutations uniquely, and ensure the degree > 1
                degrees_tuple = tuple(sorted([i, j, k], reverse=True))
                if degrees_tuple[0] <= 1:
                    continue

                # Iterate over signs (2^3 = 8 combinations)
                import itertools
                for signs in itertools.product([1, -1], repeat=3):
                    # Map signs to sorted degrees
                    P = {degrees_tuple[0]: signs[0], 
                         degrees_tuple[1]: signs[1], 
                         degrees_tuple[2]: signs[2]}

                    if check_polynomial(P, n, K):
                        # Store the polynomial definition
                        found_candidates.append({
                            'coefficients': 3,
                            'P': P,
                            'description': f"P(x) = {P[degrees_tuple[0]]}x^{degrees_tuple[0]} + {P[degrees_tuple[1]]}x^{degrees_tuple[1]} + {P[degrees_tuple[2]]}x^{degrees_tuple[2]}"
                        })
    # Remove duplicates since we iterated over permutations of degrees implicitly, though the sorted approach should minimize this risk if we handle it correctly.
    # Since we generated P based on sorted degrees, we should only have unique sets of degrees here.
    return found_candidates

